import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

function normalizeBucketName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
}

function describeError(err: unknown): string {
  if (err === undefined || err === null) {
    return "";
  }
  const parts: string[] = [];
  try {
    const e = err as any;
    const name = e?.name ?? "Error";
    const message = e?.message ?? String(err);
    parts.push(`${name}: ${message}`);
    if (e?.Code) parts.push(`Code=${e.Code}`);
    if (e?.code) parts.push(`code=${e.code}`);
    const status =
      e?.$metadata?.httpStatusCode ??
      e?.statusCode ??
      e?.status ??
      e?.httpStatusCode;
    if (status) parts.push(`httpStatusCode=${status}`);
    if (e?.cause) {
      const c = e.cause as any;
      parts.push(
        `cause=${c?.name ?? "Error"}: ${c?.message ?? String(c)}` +
          (c?.Code ? ` Code=${c.Code}` : "") +
          (c?.$metadata?.httpStatusCode
            ? ` httpStatusCode=${c.$metadata.httpStatusCode}`
            : ""),
      );
    }
    try {
      const raw = JSON.stringify(
        err,
        Object.getOwnPropertyNames(e as object),
      );
      if (raw && raw !== "{}") parts.push(`raw=${raw}`);
    } catch {
      // ignore
    }
  } catch {
    parts.push(String(err));
  }
  return parts.join(" | ");
}

async function main(): Promise<void> {
  const rawTrialId = (
    await readFile("/logs/artifacts/trial_id", "utf-8")
  ).trim();
  if (!rawTrialId) {
    console.error("trial_id is empty");
    process.exit(1);
  }
  const trialId = rawTrialId.toLowerCase();

  const workspaceName = normalizeBucketName(`harbor-ro-${trialId}`);
  const forkPrefix = normalizeBucketName(`harbor-ro-${trialId}-readonly`);

  console.log(`Creating editor workspace: ${workspaceName}`);
  const wsResp = await createWorkspace(workspaceName, {
    ttl: { days: 1 },
    enableSnapshots: true,
    credentials: { role: "Editor" },
  });
  if (wsResp.error) {
    console.error("createWorkspace failed:", describeError(wsResp.error));
    process.exit(1);
  }
  if (!wsResp.data || !wsResp.data.credentials) {
    console.error("createWorkspace returned no credentials");
    process.exit(1);
  }
  const editorBucket = wsResp.data.bucket;
  const editorCreds = wsResp.data.credentials;
  console.log(`Editor workspace bucket: ${editorBucket}`);

  // Upload notes/welcome.txt using editor credentials.
  const putEditor = await put("notes/welcome.txt", "hello readonly", {
    allowOverwrite: true,
    config: {
      bucket: editorBucket,
      accessKeyId: editorCreds.accessKeyId,
      secretAccessKey: editorCreds.secretAccessKey,
    },
  });
  if (putEditor.error) {
    console.error("editor put failed:", describeError(putEditor.error));
    process.exit(1);
  }
  console.log("Editor put succeeded");

  // Create readonly fork.
  console.log(`Creating ReadOnly fork from: ${editorBucket}`);
  const forkResp = await createForks(editorBucket, 1, {
    prefix: forkPrefix,
    credentials: { role: "ReadOnly" },
  });
  if (forkResp.error) {
    console.error("createForks failed:", describeError(forkResp.error));
    process.exit(1);
  }
  if (
    !forkResp.data ||
    !forkResp.data.forks ||
    !forkResp.data.forks[0] ||
    !forkResp.data.forks[0].credentials
  ) {
    console.error("createForks returned no fork credentials");
    process.exit(1);
  }
  const fork = forkResp.data.forks[0];
  const forkBucket = fork.bucket;
  const roCreds = fork.credentials!;
  console.log(`Fork bucket: ${forkBucket}`);

  // Attempt forbidden write using readonly credentials.
  const putForbidden = await put("notes/forbidden.txt", "should be rejected", {
    allowOverwrite: true,
    config: {
      bucket: forkBucket,
      accessKeyId: roCreds.accessKeyId,
      secretAccessKey: roCreds.secretAccessKey,
    },
  });
  if (!putForbidden.error) {
    console.error(
      "ReadOnly write unexpectedly succeeded - verification failure",
    );
    process.exit(1);
  }
  const denial = describeError(putForbidden.error);
  if (!denial) {
    console.error("ReadOnly write failed but no error description produced");
    process.exit(1);
  }
  await writeFile(
    "/home/user/tigris-task/write-denial.log",
    denial,
    "utf-8",
  );
  console.log(`Captured denial: ${denial}`);

  // Read existing welcome.txt with readonly creds.
  const getResp = await get("notes/welcome.txt", "string", {
    config: {
      bucket: forkBucket,
      accessKeyId: roCreds.accessKeyId,
      secretAccessKey: roCreds.secretAccessKey,
    },
  });
  if (getResp.error) {
    console.error("ReadOnly read failed:", describeError(getResp.error));
    process.exit(1);
  }
  const body = getResp.data;
  if (typeof body !== "string") {
    console.error("ReadOnly read returned non-string body");
    process.exit(1);
  }
  if (body !== "hello readonly") {
    console.error(
      `ReadOnly read returned unexpected body: ${JSON.stringify(body)}`,
    );
    process.exit(1);
  }
  await writeFile("/home/user/tigris-task/readback.txt", body, "utf-8");
  console.log("ReadOnly read succeeded");
  console.log("All steps verified.");
}

main().catch((err) => {
  console.error("unexpected error:", err);
  process.exit(1);
});
